{
  "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
  "version": "2.1.0",
  "runs": [
    {
      "tool": {
        "driver": {
          "name": "apsis",
          "version": "0.2.0",
          "informationUri": "https://github.com/apsis-security/apsis",
          "rules": [
            {
              "id": "assume_role",
              "name": "Cross-role assumption",
              "shortDescription": {
                "text": "The trust policy admits this principal and its policy allows sts:AssumeRole."
              },
              "fullDescription": {
                "text": "Scope the trust policy to a role ARN or aws:PrincipalArn condition, not the account root."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1078.004"
                ],
                "severity": "medium"
              },
              "helpUri": "https://github.com/apsis-security/apsis#assume_role"
            },
            {
              "id": "passrole_lambda",
              "name": "PassRole into Lambda",
              "shortDescription": {
                "text": "Pass a privileged role to a new function, then invoke it."
              },
              "fullDescription": {
                "text": "Restrict iam:PassRole with iam:PassedToService and an explicit role allowlist."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.001"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#passrole_lambda"
            },
            {
              "id": "passrole_ec2",
              "name": "PassRole into EC2",
              "shortDescription": {
                "text": "Launch an instance with an instance profile and read its metadata credentials."
              },
              "fullDescription": {
                "text": "Deny iam:PassRole for EC2 unless the caller owns the instance profile."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.001"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#passrole_ec2"
            },
            {
              "id": "passrole_cloudformation",
              "name": "PassRole into CloudFormation",
              "shortDescription": {
                "text": "Create a stack with a service role and let the template call IAM."
              },
              "fullDescription": {
                "text": "Deny cloudformation:CreateStack with a RoleARN outside the team boundary."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.001"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#passrole_cloudformation"
            },
            {
              "id": "passrole_glue",
              "name": "PassRole into Glue",
              "shortDescription": {
                "text": "Create a development endpoint that runs with the passed role."
              },
              "fullDescription": {
                "text": "Block glue:CreateDevEndpoint, or pin iam:PassRole to a known role."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.001"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#passrole_glue"
            },
            {
              "id": "passrole_sagemaker",
              "name": "PassRole into SageMaker",
              "shortDescription": {
                "text": "Create a notebook instance with the passed role, then open its terminal."
              },
              "fullDescription": {
                "text": "Deny sagemaker:CreateNotebookInstance with an arbitrary execution role."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.001"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#passrole_sagemaker"
            },
            {
              "id": "lambda_update_code",
              "name": "Rewrite a function's code",
              "shortDescription": {
                "text": "Replace the handler of an existing function that already holds a strong role."
              },
              "fullDescription": {
                "text": "Separate UpdateFunctionCode permission from InvokeFunction on production functions."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1648"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#lambda_update_code"
            },
            {
              "id": "ssm_send_command",
              "name": "Shell through SSM",
              "shortDescription": {
                "text": "Run a command on an instance and use its instance profile."
              },
              "fullDescription": {
                "text": "Scope ssm:SendCommand to document ARNs and tag-gated instances."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1651"
                ],
                "severity": "high"
              },
              "helpUri": "https://github.com/apsis-security/apsis#ssm_send_command"
            },
            {
              "id": "iam_attach_user_policy",
              "name": "Attach a policy to yourself",
              "shortDescription": {
                "text": "Attach AdministratorAccess to your own user and inherit it."
              },
              "fullDescription": {
                "text": "No human or machine identity should hold iam:AttachUserPolicy on its own ARN."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_attach_user_policy"
            },
            {
              "id": "iam_put_user_policy",
              "name": "Write an inline policy on yourself",
              "shortDescription": {
                "text": "Add an inline administrator statement to your own user."
              },
              "fullDescription": {
                "text": "Treat iam:PutUserPolicy on self as equivalent to administrator."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_put_user_policy"
            },
            {
              "id": "iam_create_policy_version",
              "name": "New version of an attached policy",
              "shortDescription": {
                "text": "Publish a new policy version that grants more than the current one."
              },
              "fullDescription": {
                "text": "CreatePolicyVersion on a policy you can also attach is a standing admin grant."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_create_policy_version"
            },
            {
              "id": "iam_set_default_policy_version",
              "name": "Activate a dormant policy version",
              "shortDescription": {
                "text": "Promote an older, wider policy version that is still stored."
              },
              "fullDescription": {
                "text": "Delete unused policy versions and block SetDefaultPolicyVersion."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_set_default_policy_version"
            },
            {
              "id": "iam_attach_role_policy",
              "name": "Attach a policy to a trusted role",
              "shortDescription": {
                "text": "Attach an administrator policy to a role you can already assume."
              },
              "fullDescription": {
                "text": "Only a break-glass pipeline should hold iam:AttachRolePolicy."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_attach_role_policy"
            },
            {
              "id": "iam_put_role_policy",
              "name": "Inline policy on a trusted role",
              "shortDescription": {
                "text": "Write an inline administrator statement onto a role you can assume."
              },
              "fullDescription": {
                "text": "Block iam:PutRolePolicy outside the IAM administration role."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_put_role_policy"
            },
            {
              "id": "iam_update_assume_role_policy",
              "name": "Rewrite a trust policy",
              "shortDescription": {
                "text": "Add yourself to a role's trust policy, then assume it."
              },
              "fullDescription": {
                "text": "iam:UpdateAssumeRolePolicy belongs only to the identity plane, never to workloads."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "critical"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_update_assume_role_policy"
            },
            {
              "id": "iam_create_access_key",
              "name": "Mint credentials for another user",
              "shortDescription": {
                "text": "Create an access key for a user with more access than you."
              },
              "fullDescription": {
                "text": "Deny iam:CreateAccessKey on all principals except a tightly held recovery role."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.001"
                ],
                "severity": "high"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_create_access_key"
            },
            {
              "id": "iam_create_login_profile",
              "name": "Set a console password for another user",
              "shortDescription": {
                "text": "Create a console login for a stronger identity without touching its keys."
              },
              "fullDescription": {
                "text": "Alert on CreateLoginProfile and UpdateLoginProfile outside the IdP flow."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.001"
                ],
                "severity": "high"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_create_login_profile"
            },
            {
              "id": "iam_add_user_to_group",
              "name": "Join a more privileged group",
              "shortDescription": {
                "text": "Add yourself to a group that carries wider policies."
              },
              "fullDescription": {
                "text": "Group membership changes are privilege changes; route them through review."
              },
              "properties": {
                "tags": [
                  "security",
                  "aws",
                  "iam",
                  "T1098.003"
                ],
                "severity": "high"
              },
              "helpUri": "https://github.com/apsis-security/apsis#iam_add_user_to_group"
            }
          ]
        }
      },
      "results": []
    }
  ]
}

